# -*- coding: utf-8 -*-
from taf.playwright.core.common import PlaywrightPagePart


class PlaywrightBasicPage(PlaywrightPagePart):
    """SBTS page base kept for backward-compatible imports."""

    def disable_message_box(self):
        """Hide transient notify.js message boxes when the SBTS UI exposes them."""
        try:
            self.page.locator(".notifyjs-corner").evaluate_all(
                "(nodes) => nodes.forEach((node) => node.style.display = 'none')"
            )
        except Exception:
            pass
